import time
from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return the parity (0 or 1) of each element of xs, in input order.

    The work is done in parallel on a thread pool, but result i always
    corresponds to xs[i], regardless of worker count or completion order.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_basic() -> None:
    assert parities([1, 2, 3, 4, 5]) == [1, 0, 1, 0, 1]


def test_empty() -> None:
    assert parities([]) == []


def test_single() -> None:
    assert parities([7]) == [1]
    assert parities([8]) == [0]


def test_negatives_and_zero() -> None:
    assert parities([-3, -2, -1, 0]) == [1, 0, 1, 0]


def test_large_ints() -> None:
    big = 10**30
    assert parities([big, big + 1, -big - 1]) == [0, 1, 1]


def test_large_input_order() -> None:
    xs = list(range(-500, 1500))
    assert parities(xs) == [x % 2 for x in xs]


def test_does_not_mutate_input() -> None:
    xs = [3, 2, 1]
    parities(xs)
    assert xs == [3, 2, 1]


def test_order_independent_of_completion_order(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    # Earlier elements finish later, so completion order is scrambled.
    xs = list(range(40))

    def slow_parity(x: int) -> int:
        time.sleep((len(xs) - x) * 0.0005)
        return x % 2

    monkeypatch.setattr(f"{__name__}.parity", slow_parity)
    assert parities(xs) == [x % 2 for x in xs]


def test_repeatable() -> None:
    xs = [5, 8, 13, 21, 34, 55, 89, 144]
    first = parities(xs)
    for _ in range(10):
        assert parities(xs) == first
